}

items.solution:
function handleWithTtl(message, seen, effect, now, ttlMs) {
  const expiresAt = seen[message.id];
  if (expiresAt !== undefined && expiresAt > now) return false;
  seen[message.id] = now + ttlMs;
  effect(message);
  return true;
}

