function processBatch(messages, seen, effect) {
  // TODO: process each new message once; return how many were processed.
}

items.solution:
function processBatch(messages, seen, effect) {
  let processed = 0;
  for (const message of messages) {
    if (seen[message.id]) continue;
    seen[message.id] = true;
    effect(message);
    processed++;
  }
  return processed;
}
